---@param cultureType XPartnerEnum.CultureType
---@return boolean
function XUiPartnerOneKeyCultureDetailItemCellView:IsCultureDone(cultureType)
    local isDone = not self._Control:GetOneKeyCultureMainControl():IsNeedCulture(cultureType)
    if isDone and cultureType == XMVCA.XPartner.Enum.CultureType.SkillLevelUp then
        isDone = self:_IsSkillWearFull()
    end
    return isDone
end

