---@return boolean
function XUiPartnerOneKeyCultureDetailItemCellView:_IsSkillWearFull()
    local partner = self._Control:GetOneKeyCultureMainControl():GetCurPartnerEntity()
    if not partner then
        return true
    end
    return #partner:GetCarryPassiveSkillGroupList() >= partner:GetQualitySkillColumnCount()
end

function XUiPartnerOneKeyCultureDetailItemCellView:_RefreshLevelUp()
    local mainControl = self._Control:GetOneKeyCultureMainControl()
    local costControl = mainControl:GetBaseCostControl()
    local partner = mainControl:GetCurPartnerEntity()
    local maxLevel = partner:GetBreakthroughLevelLimit(partner:GetBreakthroughLimit())
