function XUiPartnerOneKeyCultureDetailItemCellView:_RefreshSkillLevelUp()
    local costControl = self._Control:GetOneKeyCultureMainControl():GetBaseCostControl()
    self.TxtTitle.text = XUiHelper.GetText("PartnerOneKeyDetailSkillTitle")
