function XUiPartnerOneKeyCultureDetailItemCellView:_RefreshCostList(costList)
    -- MainView 只显示关键材料，过滤掉螺母
    local CoinId = XDataCenter.ItemManager.ItemId.Coin
    local displayList = {}
    for _, item in ipairs(costList) do
        if item.IsPartner or item.Id ~= CoinId then
            table.insert(displayList, item)
        end
    end

    self:_EnsureCostGridCount(#displayList)

    for index, item in ipairs(displayList) do
        local grid = self._CostGridList[index]
        if item.IsPartner then
            grid:RefreshCustom(item.Icon, item.Quality, item.NeedCount, item.HaveCount)
            grid:SetCustomClick(self._OnPartnerCostClick, self)
        else
            grid:Refresh(item.Id, item.Count)
        end
        grid.GameObject:SetActiveEx(true)
    end

    for i = #displayList + 1, #self._CostGridList do
        self._CostGridList[i].GameObject:SetActiveEx(false)
    end
end

function XUiPartnerOneKeyCultureDetailItemCellView:_EnsureCostGridCount(needCount)
    while #self._CostGridList < needCount do
        local ui = CS.UnityEngine.Object.Instantiate(self.GoCostGrid, self.GoCostGrid.transform.parent)
        ui.gameObject:SetActiveEx(false)
        local grid = self:_NewCostGrid(ui)
        table.insert(self._CostGridList, grid)
    end
end

function XUiPartnerOneKeyCultureDetailItemCellView:_NewCostGrid(ui)
    local XUiGridCostItem = require("XUi/XUiEquipBreakThrough/XUiGridCostItem")
    return XUiGridCostItem.New(self, ui)
end


function XUiPartnerOneKeyCultureDetailItemCellView:_OnPartnerCostClick()
    local partner = self._Control:GetOneKeyCultureMainControl():GetCurPartnerEntity()
    if not partner then
        return
    end

    local itemId = partner:GetChipItemId()
